import ULThemeCard from "@/components/ULThemeCard";
import ULThemePageLayout from "@/components/ULThemePageLayout";
import { SessionExpiredModal } from "@/components/SessionExpiredModal";
import { applyAuth0Theme } from "@/utils/theme/themeEngine";
import { applyScreenThemeOverrides } from "@/utils/theme/themeOverrides";

import ConsentActions from "./components/ConsentActions";
import Header from "./components/Header";
import ScopesList from "./components/ScopesList";
import { useConsentManager } from "./hooks/useConsentManager";

// ---------------------------------------------------------------------------
// Sobreescrituras de tema para esta pantalla específica.
// Estos valores reemplazan los del Dashboard SOLO en consent.
// Para editar el branding global, hazlo desde el Dashboard de Auth0.
// ---------------------------------------------------------------------------
const CONSENT_THEME_OVERRIDES = [
  {
    variable: "--ul-theme-page-bg-background-color",
    value: "#803571",
  },
  {
    variable: "--ul-theme-color-primary-button",
    value: "#2563eb",
  },
  {
    variable: "--ul-theme-widget-logo-url",
    value: "https://static-cdn.jtvnw.net/jtv_user_pictures/7f4f6049-7ee2-41ee-bd3a-86f9b11e2c17-profile_image-70x70.png",
  },
];

function ConsentScreen() {
  const { consent, locales, isSessionExpired, handleLogout } =
    useConsentManager();

  document.title = locales?.page?.title;

  // 1. Aplica todos los valores de branding del Dashboard
  applyAuth0Theme(consent);

  // 2. Sobreescribe SOLO las variables definidas arriba para esta pantalla
  applyScreenThemeOverrides(CONSENT_THEME_OVERRIDES);

  return (
    <>
      <ULThemePageLayout className="theme-universal">
        <ULThemeCard className="w-full max-w-[400px] gap-0">
          <Header />
          <ScopesList />
          <ConsentActions />
        </ULThemeCard>
      </ULThemePageLayout>

      {/* Modal de sesión expirada — aparece automáticamente por timer o si
          accept()/deny() fallan con error 400. Bloquea toda interacción. */}
      <SessionExpiredModal
        isVisible={isSessionExpired}
        onLogout={handleLogout}
        title={locales.sessionExpired.title}
        description={locales.sessionExpired.description}
        buttonLabel={locales.sessionExpired.logoutButton}
      />
    </>
  );
}

export default ConsentScreen;
