import type { ReactNode } from "react";

import {
  AppleIcon,
  DefaultConnectionIcon,
  GoogleIcon,
  MicrosoftIcon,
} from "@/assets/icons";

/**
 * Returns the appropriate icon component for a given Auth0 connection strategy.
 * Falls back to DefaultConnectionIcon if the strategy is not recognized.
 *
 * Common Auth0 strategies:
 *   - "google-oauth2"  → Google
 *   - "apple"          → Apple
 *   - "windowslive"    → Microsoft Account
 */
export const getIcon = (strategy?: string): ReactNode => {
  switch (strategy) {
    case "google-oauth2":
      return <GoogleIcon />;
    case "apple":
      return <AppleIcon />;
    case "windowslive":
      return <MicrosoftIcon />;
    default:
      return <DefaultConnectionIcon />;
  }
};
